import assert from'node:assert/strict';import{execFileSync,spawn,spawnSync}from'node:child_process';import{cp,mkdtemp,readFile,readlink,writeFile}from'node:fs/promises';import net from'node:net';import{tmpdir}from'node:os';import path from'node:path';import test from'node:test';async function port(){const s=net.createServer();await new Promise(r=>s.listen(0,'127.0.0.1',r));const p=s.address().port;await new Promise(r=>s.close(r));return p}
test('local bundle installs paired HTTP/CLI/MCP/worker-extension surfaces and uninstalls without data removal',async t=>{execFileSync('npm',['run','bundle'],{stdio:'pipe'});const archive='release/viqueue-v0.4.1-rc.tar.gz';execFileSync('sha256sum',['-c',`${path.basename(archive)}.sha256`],{cwd:'release',stdio:'pipe'});const work=await mkdtemp(path.join(tmpdir(),'viq-bundle-'));execFileSync('tar',['-xzf',path.resolve(archive),'-C',work]);const bundle=path.join(work,'viqueue-v0.4.1-rc');assert.equal((await readFile(path.join(bundle,'SOURCE_COMMIT'),'utf8')).trim(),execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim());assert.equal((await readFile(path.join(bundle,'extensions/viq-worker/worker-runtime.mjs'),'utf8')).includes('device_not_paired'),true);const prefix=path.join(work,'prefix');execFileSync('bash',[path.join(bundle,'install-local.sh')],{cwd:bundle,env:{...process.env,VIQ_PREFIX:prefix}});const storage=path.join(work,'data','viqueue.sqlite');const bootstrap=JSON.parse(execFileSync(path.join(prefix,'bin','viq-bootstrap'),['--storage',storage,'--id','coord','--name','Coordinator'],{encoding:'utf8'}));const listen=await port(),server=spawn(path.join(prefix,'bin','viqueue-server'),[`--port=${listen}`,`--storage=${storage}`]);t.after(()=>server.kill());const base=`http://127.0.0.1:${listen}`;for(let i=0;i<100;i++){try{if((await fetch(`${base}/health`)).ok)break}catch{}await new Promise(r=>setTimeout(r,10))}const viq=(token,...a)=>spawnSync(path.join(prefix,'bin','viq'),[...a,'--server',base,'--device-token',token],{encoding:'utf8'});assert.equal(viq(bootstrap.credential,'project','create','ABC').status,0);const pc=JSON.parse(viq(bootstrap.credential,'device','pair-code','--kind','worker').stdout),paired=await(await fetch(`${base}/v1/devices/pair`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({code:pc.code,id:'worker',name:'Worker'})})).json();assert.equal(viq(bootstrap.credential,'ticket','create','ABC','installed','--assignee','worker').status,0);assert.equal(JSON.parse(viq(paired.credential,'ticket','claim','ABC-1').stdout).ticket.id,'ABC-1');assert.equal((await fetch(base)).status,200);const mcp=spawnSync(path.join(prefix,'bin','viq-mcp'),[],{encoding:'utf8',env:{...process.env,VIQ_URL:base,VIQ_DEVICE_TOKEN:paired.credential},input:'{"jsonrpc":"2.0","id":1,"method":"initialize","params":{}}\n'});assert.equal(JSON.parse(mcp.stdout).result.serverInfo.version,'0.5.0-poc');server.kill();const second=path.join(work,'second-release');await cp(bundle,second,{recursive:true});await writeFile(path.join(second,'SOURCE_COMMIT'),`${'b'.repeat(40)}\n`);execFileSync('bash',[path.join(second,'install-local.sh')],{cwd:second,env:{...process.env,VIQ_PREFIX:prefix}});assert.match(await readlink(path.join(prefix,'lib/viqueue/current')),/b{40}$/);execFileSync('bash',[path.join(second,'rollback-local.sh')],{env:{...process.env,VIQ_PREFIX:prefix}});assert.match(await readlink(path.join(prefix,'lib/viqueue/current')),new RegExp(`${(await readFile(path.join(bundle,'SOURCE_COMMIT'),'utf8')).trim()}$`));execFileSync('bash',[path.join(bundle,'uninstall-local.sh')],{env:{...process.env,VIQ_PREFIX:prefix}});assert.equal(spawnSync(path.join(prefix,'bin','viq')).error?.code,'ENOENT');assert.equal(execFileSync('test',['-f',storage]).length,0)});
